<script setup lang="ts">
import { AlertTriangle, Bot, Check, Route, Send, UserRound } from 'lucide-vue-next'
import { ref } from 'vue'
import type { AgentPlanningMessage, AgentRoadmapGeneration, PlanningReadiness } from '@/types/product'

defineProps<{ messages: AgentPlanningMessage[]; streamingAssistant: string; question: string; canGenerate: boolean; readiness?: PlanningReadiness | null; loading: boolean; generating: boolean; generation: AgentRoadmapGeneration | null; error: string | null; disabled?: boolean }>()
const emit = defineEmits<{ send: [message: string]; generate: []; retry: []; 'retry-generation': [] }>()
const input = ref('')
function submit() { const value = input.value.trim(); if (!value) return; emit('send', value); input.value = '' }
const phaseLabels: Record<AgentRoadmapGeneration['phase'], string> = { domain: '整理能力域', module: '组织能力模块', unit: '安排近期单元', critic: '校验路线结构', completed: '路线已生成', failed: '生成失败' }
function phaseLabel(phase: AgentRoadmapGeneration['phase'] | undefined) { return phase ? phaseLabels[phase] : '准备生成' }
const blockerLabels: Record<string, string> = { assessment_not_terminal: '请先完成或放弃水平测评。', requirements_not_confirmed: '请先审核并确认需求摘要。', stage_not_ready: '当前阶段尚未进入路线生成门禁。' }
function blockerLabel(value: string) { return blockerLabels[value] ?? value }
</script>

<template>
  <section class="planning-chat" aria-labelledby="planning-chat-title">
    <header class="chat-header"><div class="chat-kicker"><Bot :size="16" aria-hidden="true" /><span id="planning-chat-title">知行 Planner</span></div><span class="chat-state">自然对话 · 原话会保留</span></header>
    <div class="message-list">
      <article v-for="message in messages" :key="message.id" class="message" :class="message.role"><div class="avatar"><Bot v-if="message.role === 'assistant'" :size="13" aria-hidden="true" /><UserRound v-else :size="13" aria-hidden="true" /></div><div class="message-copy"><small>{{ message.role === 'assistant' ? '知行 Planner' : '你' }}</small><p>{{ message.content }}</p></div></article>
      <article v-if="streamingAssistant" class="message assistant active"><div class="avatar"><Bot :size="13" aria-hidden="true" /></div><div class="message-copy"><small>知行 Planner · 正在回复</small><p>{{ streamingAssistant }}</p></div></article>
    </div>
    <div v-if="generation && ['queued', 'running'].includes(generation.status)" class="generation-progress" aria-live="polite"><span class="progress-mark"><span /></span><div><small>路线生成中 · 第 {{ generation.attemptCount || 1 }} 次</small><strong>{{ phaseLabel(generation.phase) }}</strong><span>正在根据已保存的对话整理路线，刷新页面后会继续显示真实进度。</span></div></div>
    <div v-else-if="generation && ['failed', 'interrupted'].includes(generation.status)" class="generation-failure" role="alert"><AlertTriangle :size="16" aria-hidden="true" /><div><small>路线生成未完成</small><strong>{{ generation.failureMessage || '路线生成失败，请重试。' }}</strong><span>原始对话和已确认信息已经保留，可以继续补充或重新生成。</span><button class="retry-button" type="button" :disabled="generating" @click="emit('retry-generation')"><Route :size="13" aria-hidden="true" />{{ generating ? '正在重试…' : '重试生成路线' }}</button></div></div>
    <div v-else-if="error" class="planning-error" role="alert"><AlertTriangle :size="14" aria-hidden="true" /><span>{{ error }}</span></div>
    <div v-if="canGenerate" class="generation-ready"><Route :size="15" aria-hidden="true" /><div><strong>已经可以生成初版学习路线</strong><span>测评已结束，需求摘要也已由你确认。</span></div></div><div v-else-if="readiness?.blockers?.length" class="generation-blocked"><Route :size="15" aria-hidden="true" /><div><strong>路线还不能生成</strong><span v-for="blocker in readiness.blockers" :key="blocker">{{ blockerLabel(blocker) }}</span></div></div><div v-if="disabled" class="chat-disabled" role="status">评估进行中，请在上方卡片中完成当前步骤。</div><div v-else class="next-question"><small>下一步可以聊聊</small><strong>{{ question || '请继续补充当前阶段所需的信息。' }}</strong></div>
    <form class="composer" @submit.prevent="submit"><textarea v-model="input" rows="3" :disabled="loading || generating || disabled" aria-label="发送给知行 Planner" placeholder="用自己的话回答，补充一个具体例子" @keydown.meta.enter.prevent="submit" @keydown.ctrl.enter.prevent="submit" /><div class="composer-actions"><button class="secondary-button" type="button" :disabled="loading || generating || disabled || !canGenerate || generation?.status === 'succeeded'" @click="emit('generate')"><Check v-if="generation?.status === 'succeeded'" :size="14" aria-hidden="true" /><Route v-else :size="14" aria-hidden="true" />{{ generating ? '正在生成路线…' : generation?.status === 'succeeded' ? '路线已生成' : '现在生成路线' }}</button><button class="primary-button" type="submit" :disabled="loading || generating || disabled || !input.trim()"><Send :size="14" aria-hidden="true" />发送</button></div></form>
  </section>
</template>

<style scoped>
.planning-chat { min-width: 0; }.chat-header { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding-bottom: 12px; border-bottom: 1px solid var(--line); }.chat-kicker { display: inline-flex; align-items: center; gap: 8px; color: var(--blue); font: 10px var(--mono); }.chat-state { color: var(--muted); font: 9px var(--mono); }.message-list { display: grid; gap: 18px; max-height: 560px; overflow: auto; padding: 20px 3px 12px; }.message { display: flex; align-items: start; gap: 10px; max-width: 84%; }.message.user { justify-self: end; flex-direction: row-reverse; }.avatar { display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto; width: 28px; height: 28px; border: 1px solid var(--line); background: var(--paper-deep); color: var(--blue); }.message.user .avatar { border-color: #ddb79f; background: var(--orange-soft); color: #684e40; }.message-copy { min-width: 0; }.message-copy small, .next-question small, .generation-progress small, .generation-failure small { color: var(--muted); font: 8px var(--mono); }.message-copy p { margin: 5px 0 0; padding: 10px 12px; border: 1px solid var(--line-soft); background: var(--paper-deep); color: #53605a; font-size: 12px; line-height: 1.65; white-space: pre-wrap; }.message.user .message-copy p { border-color: #ead6c7; background: var(--orange-soft); color: #684e40; }.message.active .message-copy p { border-color: #b5bdf0; background: var(--blue-soft); color: var(--ink); }.generation-ready { display: flex; align-items: start; gap: 9px; margin: 6px 0 0 38px; padding: 11px 13px; border-left: 2px solid var(--green); background: var(--green-soft); color: var(--green); }.generation-ready strong { display: block; color: var(--ink); font-size: 12px; font-weight: 500; }.generation-ready span { display: block; margin-top: 4px; color: var(--muted); font-size: 10px; line-height: 1.5; }.next-question { margin: 5px 0 0 38px; padding: 12px 13px; border-left: 2px solid var(--orange); background: var(--paper-muted); }.next-question strong { display: block; margin-top: 5px; color: var(--ink); font: 400 15px/1.45 var(--serif); }.generation-progress, .generation-failure, .planning-error { display: flex; align-items: start; gap: 10px; margin: 8px 0 0 38px; padding: 12px 13px; border-left: 2px solid var(--blue); background: var(--blue-soft); }.generation-progress strong, .generation-failure strong { display: block; margin-top: 4px; color: var(--ink); font-size: 12px; font-weight: 500; }.generation-progress span:last-child, .generation-failure span { display: block; margin-top: 4px; color: var(--muted); font-size: 10px; line-height: 1.5; }.progress-mark { display: inline-flex; width: 16px; height: 16px; border: 1px solid var(--blue); border-radius: 50%; padding: 3px; }.progress-mark span { display: block; width: 100%; height: 100%; border-radius: 50%; background: var(--blue); animation: planning-pulse 1.2s ease-in-out infinite; }.generation-failure { border-left-color: var(--orange); background: var(--orange-soft); }.generation-failure > svg, .planning-error > svg { flex: 0 0 auto; color: var(--orange); }.retry-button { display: inline-flex; align-items: center; gap: 6px; margin-top: 10px; min-height: 30px; border: 1px solid var(--line); background: var(--white); color: var(--ink); cursor: pointer; }.planning-error { border-left-color: var(--orange); background: var(--orange-soft); color: var(--ink); font-size: 11px; }.composer { display: grid; gap: 9px; margin-top: 14px; padding-top: 14px; border-top: 2px solid var(--blue); }.composer textarea { width: 100%; resize: vertical; padding: 11px 12px; border: 1px solid var(--line); outline: none; background: var(--white); color: var(--ink); font: 12px/1.6 var(--sans); }.composer textarea:focus { border-color: var(--blue); }.composer-actions { display: flex; justify-content: end; gap: 8px; }.composer-actions button { display: inline-flex; align-items: center; gap: 6px; min-height: 34px; cursor: pointer; }.primary-button:disabled, .secondary-button:disabled, .retry-button:disabled { opacity: .55; cursor: wait; }
 .generation-blocked { display: flex; align-items: start; gap: 9px; margin: 6px 0 0 38px; padding: 11px 13px; border-left: 2px solid var(--orange); background: var(--orange-soft); color: var(--orange); }.generation-blocked strong { display: block; color: var(--ink); font-size: 12px; }.generation-blocked span { display: block; margin-top: 4px; color: var(--muted); font-size: 10px; line-height: 1.5; }.chat-disabled { margin: 6px 0 0 38px; padding: 10px 13px; background: var(--paper-muted); color: var(--muted); font: 9px var(--mono); }
@keyframes planning-pulse { 0%, 100% { opacity: .35; transform: scale(.75); } 50% { opacity: 1; transform: scale(1); } }
@media (max-width: 600px) { .message { max-width: 94%; }.composer-actions { flex-direction: column; }.composer-actions button { justify-content: center; } }
</style>
